import{_ as a,o as n,c as o,aw as l}from"./chunks/framework.DLufY-ao.js";const A=JSON.parse('{"title":"Программная навигация","description":"","frontmatter":{},"headers":[],"relativePath":"wiki/dev-commit/framework-vue/vue-router/variants/navigation.md","filePath":"wiki/dev-commit/framework-vue/vue-router/variants/navigation.md"}'),e={name:"wiki/dev-commit/framework-vue/vue-router/variants/navigation.md"};function p(t,s,r,c,i,y){return n(),o("div",null,[...s[0]||(s[0]=[l(`<h1 id="программная-навигация" tabindex="-1">Программная навигация <a class="header-anchor" href="#программная-навигация" aria-label="Permalink to &quot;Программная навигация&quot;">​</a></h1><h2 id="информация" tabindex="-1">Информация <a class="header-anchor" href="#информация" aria-label="Permalink to &quot;Информация&quot;">​</a></h2><ul><li>Внутри экземпляра Vue у вас есть доступ к экземпляру маршрутизатора через <code>$router</code>. Поэтому можно вызвать <code>this.$router.push</code></li></ul><h2 id="методы" tabindex="-1">Методы <a class="header-anchor" href="#методы" aria-label="Permalink to &quot;Методы&quot;">​</a></h2><ul><li><em><code>router.push(location, onComplete?, onAbort?)</code></em> (аналог: <em>window.history.pushState</em>) - для перехода к новому URL. Метод добавляет новую запись в историю навигации, что позволяет клику пользователя по кнопке &quot;назад&quot; в браузере сработать привычным образом. В качестве аргумента можно передать строку или объект, описывающий маршрут</li><li><em><code>router.replace(location, onComplete?, onAbort?)</code></em> (аналог: <em>window.history.replaceState</em>) - действует как router.push, с той лишь разницей, что переход осуществляется без добавления новой записи в историю навигации, а заменяет текущую запись в нём</li><li><em><code>router.go(n)</code></em> (аналог: <em>window.history.go</em>) - метод принимает параметром целое число, которое указывает на сколько шагов необходимо перейти по истории навигации</li></ul><h2 id="код" tabindex="-1">Код <a class="header-anchor" href="#код" aria-label="Permalink to &quot;Код&quot;">​</a></h2><h3 id="router-push" tabindex="-1"><code>router.push</code> <a class="header-anchor" href="#router-push" aria-label="Permalink to &quot;\`router.push\`&quot;">​</a></h3><div class="language-bash"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki one-light vp-code" tabindex="0"><code><span class="line"><span style="color:#383A42;">&lt;router-link :</span><span style="color:#E45649;">to</span><span style="color:#383A42;">=</span><span style="color:#50A14F;">&quot;...&quot;</span><span style="color:#383A42;">&gt;	</span><span style="color:#A0A1A7;font-style:italic;"># Декларативная запись</span></span>
<span class="line"><span style="color:#4078F2;">router.push(...</span><span style="color:#383A42;">)        </span><span style="color:#A0A1A7;font-style:italic;"># Программная запись</span></span></code></pre></div><div class="language-js"><button title="Copy Code" class="copy"></button><span class="lang">js</span><pre class="shiki one-light vp-code" tabindex="0"><code><span class="line"><span style="color:#A0A1A7;font-style:italic;">// Строка</span></span>
<span class="line"><span style="color:#383A42;">router.</span><span style="color:#4078F2;">push</span><span style="color:#383A42;">(</span><span style="color:#50A14F;">&quot;home&quot;</span><span style="color:#383A42;">);</span></span>
<span class="line"></span>
<span class="line"><span style="color:#A0A1A7;font-style:italic;">// Объект</span></span>
<span class="line"><span style="color:#383A42;">router.</span><span style="color:#4078F2;">push</span><span style="color:#383A42;">({ </span><span style="color:#E45649;">path</span><span style="color:#0184BC;">:</span><span style="color:#50A14F;"> &quot;home&quot;</span><span style="color:#383A42;"> });</span></span>
<span class="line"></span>
<span class="line"><span style="color:#A0A1A7;font-style:italic;">// Именованный маршрут</span></span>
<span class="line"><span style="color:#383A42;">router.</span><span style="color:#4078F2;">push</span><span style="color:#383A42;">({ </span><span style="color:#E45649;">name</span><span style="color:#0184BC;">:</span><span style="color:#50A14F;"> &quot;user&quot;</span><span style="color:#383A42;">, </span><span style="color:#E45649;">params</span><span style="color:#0184BC;">:</span><span style="color:#383A42;"> { </span><span style="color:#E45649;">userId</span><span style="color:#0184BC;">:</span><span style="color:#50A14F;"> &quot;123&quot;</span><span style="color:#383A42;"> } });</span></span>
<span class="line"></span>
<span class="line"><span style="color:#A0A1A7;font-style:italic;">// Со строкой запроса, получится /register?plan=private</span></span>
<span class="line"><span style="color:#383A42;">router.</span><span style="color:#4078F2;">push</span><span style="color:#383A42;">({ </span><span style="color:#E45649;">path</span><span style="color:#0184BC;">:</span><span style="color:#50A14F;"> &quot;register&quot;</span><span style="color:#383A42;">, </span><span style="color:#E45649;">query</span><span style="color:#0184BC;">:</span><span style="color:#383A42;"> { </span><span style="color:#E45649;">plan</span><span style="color:#0184BC;">:</span><span style="color:#50A14F;"> &quot;private&quot;</span><span style="color:#383A42;"> } });</span></span></code></pre></div><h3 id="router-replace" tabindex="-1"><code>router.replace</code> <a class="header-anchor" href="#router-replace" aria-label="Permalink to &quot;\`router.replace\`&quot;">​</a></h3><div class="language-bash"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki one-light vp-code" tabindex="0"><code><span class="line"><span style="color:#383A42;">&lt;router-link :</span><span style="color:#E45649;">to</span><span style="color:#383A42;">=</span><span style="color:#50A14F;">&quot;...&quot;</span><span style="color:#4078F2;"> replace</span><span style="color:#383A42;">&gt; </span><span style="color:#A0A1A7;font-style:italic;"># Декларативная запись</span></span>
<span class="line"><span style="color:#4078F2;">router.replace(...</span><span style="color:#383A42;">)             </span><span style="color:#A0A1A7;font-style:italic;"># Программная запись</span></span></code></pre></div><h3 id="router-go" tabindex="-1"><code>router.go</code> <a class="header-anchor" href="#router-go" aria-label="Permalink to &quot;\`router.go\`&quot;">​</a></h3><div class="language-js"><button title="Copy Code" class="copy"></button><span class="lang">js</span><pre class="shiki one-light vp-code" tabindex="0"><code><span class="line"><span style="color:#A0A1A7;font-style:italic;">// Перейти на одну запись вперёд, эквивалентно history.forward()</span></span>
<span class="line"><span style="color:#383A42;">router.</span><span style="color:#4078F2;">go</span><span style="color:#383A42;">(</span><span style="color:#986801;">1</span><span style="color:#383A42;">);</span></span>
<span class="line"></span>
<span class="line"><span style="color:#A0A1A7;font-style:italic;">// Перейти на одну запись назад, эквивалентно history.back()</span></span>
<span class="line"><span style="color:#383A42;">router.</span><span style="color:#4078F2;">go</span><span style="color:#383A42;">(</span><span style="color:#0184BC;">-</span><span style="color:#986801;">1</span><span style="color:#383A42;">);</span></span>
<span class="line"></span>
<span class="line"><span style="color:#A0A1A7;font-style:italic;">// Перейти на 3 записи вперёд</span></span>
<span class="line"><span style="color:#383A42;">router.</span><span style="color:#4078F2;">go</span><span style="color:#383A42;">(</span><span style="color:#986801;">3</span><span style="color:#383A42;">);</span></span>
<span class="line"></span>
<span class="line"><span style="color:#A0A1A7;font-style:italic;">// Если записей в истории недостаточно много, переход просто не произойдёт</span></span>
<span class="line"><span style="color:#383A42;">router.</span><span style="color:#4078F2;">go</span><span style="color:#383A42;">(</span><span style="color:#0184BC;">-</span><span style="color:#986801;">100</span><span style="color:#383A42;">);</span></span>
<span class="line"><span style="color:#383A42;">router.</span><span style="color:#4078F2;">go</span><span style="color:#383A42;">(</span><span style="color:#986801;">100</span><span style="color:#383A42;">);</span></span></code></pre></div>`,13)])])}const d=a(e,[["render",p]]);export{A as __pageData,d as default};
